    <main>
      <div class="illustration" aria-hidden="true">
        <svg viewBox="0 0 24 24" fill="none">
          <path d="M7.5 10V8a4.5 4.5 0 019 0v2" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/>
          <rect x="5" y="10" width="14" height="10" rx="3" stroke="currentColor" stroke-width="1.8"/>
          <circle cx="12" cy="15" r="1.3" fill="currentColor"/>
        </svg>
      </div>

      <h1>أدخل الرمز</h1>
      <p class="description">
        أرسلنا رمزًا مكونًا من 6 أرقام إلى
        <bdi class="phone" dir="ltr">+966 55 123 4567</bdi>
      </p>

      <form class="otp-form" id="otpForm" novalidate>
        <label class="otp-label" for="otp-1">رمز التحقق</label>

        <div class="otp-inputs" id="otpInputs" dir="ltr">
          <input class="otp-input" id="otp-1" type="text" inputmode="numeric" autocomplete="one-time-code" maxlength="1" aria-label="الرقم 1">
          <input class="otp-input" id="otp-2" type="text" inputmode="numeric" autocomplete="one-time-code" maxlength="1" aria-label="الرقم 2">
          <input class="otp-input" id="otp-3" type="text" inputmode="numeric" autocomplete="one-time-code" maxlength="1" aria-label="الرقم 3">
          <input class="otp-input" id="otp-4" type="text" inputmode="numeric" autocomplete="one-time-code" maxlength="1" aria-label="الرقم 4">
          <input class="otp-input" id="otp-5" type="text" inputmode="numeric" autocomplete="one-time-code" maxlength="1" aria-label="الرقم 5">
          <input class="otp-input" id="otp-6" type="text" inputmode="numeric" autocomplete="one-time-code" maxlength="1" aria-label="الرقم 6">
        </div>

        <p class="error-message" id="errorMessage" role="alert" aria-live="polite"></p>

        <div class="resend-row">
          <span id="resendText">إعادة الإرسال خلال 0:45</span>
          <button class="resend-button" id="resendButton" type="button" hidden>إعادة إرسال الرمز</button>
        </div>

        <button class="verify-button" id="verifyButton" type="submit" disabled>تحقق</button>

        <p class="security-note">
          <svg viewBox="0 0 24 24" fill="none" aria-hidden="true">
            <path d="M12 3l7 3v5c0 4.5-2.8 8.1-7 10-4.2-1.9-7-5.5-7-10V6l7-3z" stroke="currentColor" stroke-width="1.7" stroke-linejoin="round"/>
            <path d="M9 12l2 2 4-4" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"/>
          </svg>
          <span>لا تشارك رمز التحقق مع أي شخص</span>
        </p>
      </form>
    </main>
