    function updateVerificationState() {
      const code = inputs.map(input => input.value).join("");
      const complete = code.length === 6;
      verifyButton.disabled = !complete;
      inputs.forEach(input => input.classList.toggle("is-filled", input.value !== ""));
    }

    inputs.forEach((input, index) => {
      input.addEventListener("input", () => {
        input.value = input.value.replace(/\D/g, "").slice(0, 1);
        errorMessage.textContent = "";
        updateVerificationState();

        if (input.value && index < inputs.length - 1) {
          inputs[index + 1].focus();
        }
      });

      input.addEventListener("keydown", event => {
        if (event.key === "Backspace" && !input.value && index > 0) {
          inputs[index - 1].focus();
          inputs[index - 1].value = "";
          updateVerificationState();
        }

        if (event.key === "ArrowLeft" && index > 0) {
          inputs[index - 1].focus();
        }

        if (event.key === "ArrowRight" && index < inputs.length - 1) {
          inputs[index + 1].focus();
        }
      });

      input.addEventListener("paste", event => {
        event.preventDefault();
        const digits = event.clipboardData.getData("text").replace(/\D/g, "").slice(0, 6);
        digits.split("").forEach((digit, digitIndex) => {
          if (inputs[digitIndex]) inputs[digitIndex].value = digit;
        });
        updateVerificationState();
        inputs[Math.min(digits.length, inputs.length - 1)].focus();
      });
    });

    form.addEventListener("submit", event => {
      event.preventDefault();
      const code = inputs.map(input => input.value).join("");

      if (code.length !== 6) {
        errorMessage.textContent = "يرجى إدخال الرمز المكوّن من 6 أرقام.";
        inputs.find(input => !input.value)?.focus();
        return;
      }

      verifyButton.textContent = "تم التحقق";
      verifyButton.disabled = true;
      errorMessage.textContent = "";
    });

    resendButton.addEventListener("click", () => {
      remainingSeconds = 45;
      resendButton.hidden = true;
      resendText.hidden = false;
      updateCountdown();

      const restarted = setInterval(() => {
        remainingSeconds -= 1;

        if (remainingSeconds <= 0) {
          clearInterval(restarted);
          resendText.hidden = true;
          resendButton.hidden = false;
        } else {
          updateCountdown();
        }
      }, 1000);

      inputs.forEach(input => {
        input.value = "";
        input.classList.remove("is-filled");
      });
      updateVerificationState();
      inputs[0].focus();
    });

    updateCountdown();
  </script>
